import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;class PublicExamplesTest{@Test void publishedCountsAndSeparateEqualLookup(){String[]in={"s17","s18","s17"};Object result=TaskBinding.count(in);assertEquals(Set.of("s17","s18"),TaskBinding.unique(result));assertEquals(Map.of("s17",2,"s18",1),TaskBinding.counts(result));assertEquals(2,TaskBinding.lookup(result,"s17"));assertArrayEquals(new String[]{"s17","s18","s17"},in);}}
